import os
import numpy as np
import numba
from chess_engine.constants import MAX_PLY

# Fast Neural Network Inference Engine using Numba
# This script loads the weights generated by train.py and provides an @njit compiled function
# to quickly evaluate a chess position (represented as a 768-dimensional feature vector).

WEIGHTS_DIR = os.path.join(os.path.dirname(__file__), 'weights')

# Global variables to hold the network weights for 4 layers (FP32 architecture)
FC1_WEIGHT = np.zeros((256, 45056), dtype=np.float32)
FC1_BIAS = np.zeros((256,), dtype=np.float32)
FC2_WEIGHT = np.zeros((32, 512), dtype=np.float32)
FC2_BIAS = np.zeros((32,), dtype=np.float32)
FC3_WEIGHT = np.zeros((32, 32), dtype=np.float32)
FC3_BIAS = np.zeros((32,), dtype=np.float32)
FC4_WEIGHT = np.zeros((1, 32), dtype=np.float32)
FC4_BIAS = np.zeros((1,), dtype=np.float32)

def load_weights():
    """Loads the neural network weights from disk."""
    global FC1_WEIGHT, FC1_BIAS, FC2_WEIGHT, FC2_BIAS, FC3_WEIGHT, FC3_BIAS, FC4_WEIGHT, FC4_BIAS
    try:
        if not os.path.exists(WEIGHTS_DIR):
            print("Weights directory not found. Please run ml_eval/train.py first.")
            return False
            
        FC1_WEIGHT = np.load(os.path.join(WEIGHTS_DIR, 'fc1_weight.npy')).astype(np.float32)
        FC1_BIAS = np.load(os.path.join(WEIGHTS_DIR, 'fc1_bias.npy')).astype(np.float32)
        FC2_WEIGHT = np.load(os.path.join(WEIGHTS_DIR, 'fc2_weight.npy')).astype(np.float32)
        FC2_BIAS = np.load(os.path.join(WEIGHTS_DIR, 'fc2_bias.npy')).astype(np.float32)
        FC3_WEIGHT = np.load(os.path.join(WEIGHTS_DIR, 'fc3_weight.npy')).astype(np.float32)
        FC3_BIAS = np.load(os.path.join(WEIGHTS_DIR, 'fc3_bias.npy')).astype(np.float32)
        FC4_WEIGHT = np.load(os.path.join(WEIGHTS_DIR, 'fc4_weight.npy')).astype(np.float32)
        FC4_BIAS = np.load(os.path.join(WEIGHTS_DIR, 'fc4_bias.npy')).astype(np.float32)
        
        print(f"Loaded 4-layer NNUE (FP32) weights successfully. Shapes:")
        print(f"FC1: {FC1_WEIGHT.shape}, FC2: {FC2_WEIGHT.shape}, FC3: {FC3_WEIGHT.shape}, FC4: {FC4_WEIGHT.shape}")
        return True
    except Exception as e:
        print(f"Failed to load neural network weights: {e}")
        return False

# Initialize weights on import
weights_loaded = load_weights()

@numba.njit(numba.void(numba.types.Array(numba.uint64, 1, 'C'), numba.float32[:, :, :]), fastmath=True, cache=True)
def init_accumulator(piece_bbs, accumulator_stack):
    """
    Initializes the accumulator stack at ply 0 from scratch using the full bitboards.
    Computes both White and Black (mirrored) perspectives for HalfKA.
    """
    for i in range(256):
        accumulator_stack[0, 0, i] = FC1_BIAS[i]
        accumulator_stack[0, 1, i] = FC1_BIAS[i]
        
    king_w_bb = piece_bbs[5]
    king_w_sq = 0
    if king_w_bb:
        lsb = king_w_bb & (~king_w_bb + np.uint64(1))
        tmp = lsb >> np.uint64(1)
        while tmp:
            king_w_sq += 1
            tmp >>= np.uint64(1)
            
    king_b_bb = piece_bbs[11]
    king_b_sq = 0
    if king_b_bb:
        lsb = king_b_bb & (~king_b_bb + np.uint64(1))
        tmp = lsb >> np.uint64(1)
        while tmp:
            king_b_sq += 1
            tmp >>= np.uint64(1)
            
    bucket_w = king_w_sq
    for p_idx in range(12):
        if p_idx == 5: continue
        mapped_type_w = p_idx if p_idx < 5 else (p_idx - 1)
        bb = piece_bbs[p_idx]
        while bb:
            lsb = bb & (~bb + np.uint64(1))
            sq = 0
            tmp = lsb >> np.uint64(1)
            while tmp:
                sq += 1
                tmp >>= np.uint64(1)
            f_w = bucket_w * 704 + mapped_type_w * 64 + sq
            for i in range(256):
                accumulator_stack[0, 0, i] += FC1_WEIGHT[i, f_w]
            bb &= bb - np.uint64(1)
            
    bucket_b = king_b_sq ^ 56
    for p_idx in range(12):
        if p_idx == 11: continue
        mapped_type_b = (p_idx + 5) if p_idx < 6 else (p_idx - 6)
        bb = piece_bbs[p_idx]
        while bb:
            lsb = bb & (~bb + np.uint64(1))
            sq = 0
            tmp = lsb >> np.uint64(1)
            while tmp:
                sq += 1
                tmp >>= np.uint64(1)
            sq_b = sq ^ 56
            f_b = bucket_b * 704 + mapped_type_b * 64 + sq_b
            for i in range(256):
                accumulator_stack[0, 1, i] += FC1_WEIGHT[i, f_b]
            bb &= bb - np.uint64(1)

@numba.njit(numba.void(numba.types.Array(numba.uint64, 1, 'C'), numba.int32[:], numba.int32[:], numba.int32, numba.float32[:, :, :]), fastmath=True, cache=True)
def update_accumulator(piece_bbs, added_features, removed_features, ply, accumulator_stack):
    """
    Incrementally updates both White and Black accumulators from ply-1 to ply.
    If a king moves, fires a full refresh for its side.
    """
    white_king_moved = False
    black_king_moved = False
    
    for f in added_features:
        if f != -1:
            p_idx = f // 64
            if p_idx == 5: white_king_moved = True
            elif p_idx == 11: black_king_moved = True

    king_w_bb = piece_bbs[5]
    king_w_sq = 0
    if king_w_bb:
        lsb = king_w_bb & (~king_w_bb + np.uint64(1))
        tmp = lsb >> np.uint64(1)
        while tmp:
            king_w_sq += 1
            tmp >>= np.uint64(1)
            
    king_b_bb = piece_bbs[11]
    king_b_sq = 0
    if king_b_bb:
        lsb = king_b_bb & (~king_b_bb + np.uint64(1))
        tmp = lsb >> np.uint64(1)
        while tmp:
            king_b_sq += 1
            tmp >>= np.uint64(1)
            
    bucket_w = king_w_sq
    bucket_b = king_b_sq ^ 56
            
    # --- White Update ---
    if white_king_moved:
        for i in range(256):
            accumulator_stack[ply, 0, i] = FC1_BIAS[i]
        for p_idx in range(12):
            if p_idx == 5: continue
            mapped_type_w = p_idx if p_idx < 5 else (p_idx - 1)
            bb = piece_bbs[p_idx]
            while bb:
                lsb = bb & (~bb + np.uint64(1))
                sq = 0
                tmp = lsb >> np.uint64(1)
                while tmp:
                    sq += 1
                    tmp >>= np.uint64(1)
                f_w = bucket_w * 704 + mapped_type_w * 64 + sq
                for i in range(256):
                    accumulator_stack[ply, 0, i] += FC1_WEIGHT[i, f_w]
                bb &= bb - np.uint64(1)
    else:
        for i in range(256):
            accumulator_stack[ply, 0, i] = accumulator_stack[ply - 1, 0, i]
        for f in added_features:
            if f != -1:
                p_idx = f // 64
                if p_idx == 5: continue
                mapped_type_w = p_idx if p_idx < 5 else (p_idx - 1)
                sq = f % 64
                f_w = bucket_w * 704 + mapped_type_w * 64 + sq
                for i in range(256):
                    accumulator_stack[ply, 0, i] += FC1_WEIGHT[i, f_w]
        for f in removed_features:
            if f != -1:
                p_idx = f // 64
                if p_idx == 5: continue
                mapped_type_w = p_idx if p_idx < 5 else (p_idx - 1)
                sq = f % 64
                f_w = bucket_w * 704 + mapped_type_w * 64 + sq
                for i in range(256):
                    accumulator_stack[ply, 0, i] -= FC1_WEIGHT[i, f_w]

    # --- Black Update ---
    if black_king_moved:
        for i in range(256):
            accumulator_stack[ply, 1, i] = FC1_BIAS[i]
        for p_idx in range(12):
            if p_idx == 11: continue
            mapped_type_b = (p_idx + 5) if p_idx < 6 else (p_idx - 6)
            bb = piece_bbs[p_idx]
            while bb:
                lsb = bb & (~bb + np.uint64(1))
                sq = 0
                tmp = lsb >> np.uint64(1)
                while tmp:
                    sq += 1
                    tmp >>= np.uint64(1)
                sq_b = sq ^ 56
                f_b = bucket_b * 704 + mapped_type_b * 64 + sq_b
                for i in range(256):
                    accumulator_stack[ply, 1, i] += FC1_WEIGHT[i, f_b]
                bb &= bb - np.uint64(1)
    else:
        for i in range(256):
            accumulator_stack[ply, 1, i] = accumulator_stack[ply - 1, 1, i]
        for f in added_features:
            if f != -1:
                p_idx = f // 64
                if p_idx == 11: continue
                mapped_type_b = (p_idx + 5) if p_idx < 6 else (p_idx - 6)
                sq = f % 64
                sq_b = sq ^ 56
                f_b = bucket_b * 704 + mapped_type_b * 64 + sq_b
                for i in range(256):
                    accumulator_stack[ply, 1, i] += FC1_WEIGHT[i, f_b]
        for f in removed_features:
            if f != -1:
                p_idx = f // 64
                if p_idx == 11: continue
                mapped_type_b = (p_idx + 5) if p_idx < 6 else (p_idx - 6)
                sq = f % 64
                sq_b = sq ^ 56
                f_b = bucket_b * 704 + mapped_type_b * 64 + sq_b
                for i in range(256):
                    accumulator_stack[ply, 1, i] -= FC1_WEIGHT[i, f_b]

@numba.njit(numba.void(numba.int32, numba.float32[:, :, :]), fastmath=True, cache=True)
def copy_accumulator(ply, accumulator_stack):
    for i in range(256):
        accumulator_stack[ply, 0, i] = accumulator_stack[ply - 1, 0, i]
        accumulator_stack[ply, 1, i] = accumulator_stack[ply - 1, 1, i]

@numba.njit(numba.float32(numba.int32, numba.int32, numba.float32[:, :, :]), fastmath=True, cache=True)
def nnue_forward_incremental(ply, stm, accumulator_stack):
    nstm = stm ^ 1
    
    # Layer 1: ClippedReLU (0, 127.0) concatenated
    layer1 = np.zeros(512, dtype=np.float32)
    for i in range(256):
        layer1[i] = max(0.0, min(127.0, accumulator_stack[ply, stm, i]))
        layer1[256 + i] = max(0.0, min(127.0, accumulator_stack[ply, nstm, i]))
        
    # Layer 2: ClippedReLU(Linear)
    layer2 = np.zeros(32, dtype=np.float32)
    for i in range(32):
        acc = FC2_BIAS[i]
        for j in range(512):
            acc += FC2_WEIGHT[i, j] * layer1[j]
        layer2[i] = max(0.0, min(127.0, acc))
        
    # Layer 3: ClippedReLU(Linear)
    layer3 = np.zeros(32, dtype=np.float32)
    for i in range(32):
        acc = FC3_BIAS[i]
        for j in range(32):
            acc += FC3_WEIGHT[i, j] * layer2[j]
        layer3[i] = max(0.0, min(127.0, acc))
        
    # Layer 4: Linear
    output = FC4_BIAS[0]
    for i in range(32):
        output += FC4_WEIGHT[0, i] * layer3[i]
            
    return output

@numba.njit(numba.types.Tuple((numba.int32[:], numba.int32[:]))(numba.types.Array(numba.uint64, 1, 'C'), numba.types.Array(numba.uint64, 1, 'C')), fastmath=True, cache=True)
def get_bb_differences(old_piece_bbs, new_piece_bbs):
    """
    Computes the added and removed feature indices by diffing two piece_bbs arrays.
    Returns (added_features, removed_features) padded with -1 up to capacity 4.
    """
    # Capacity 8: handles castling (2 rook + 2 king moves = 4 pairs)
    # and en passant (1 move + 1 capture = at most 4 diffs)
    # SF18 uses a fixed-size array per diff direction; we mirror that here.
    added = np.full(8, -1, dtype=np.int32)
    removed = np.full(8, -1, dtype=np.int32)
    add_idx = 0
    rem_idx = 0
    
    for piece_idx in range(12):
        diff = old_piece_bbs[piece_idx] ^ new_piece_bbs[piece_idx]
        offset = piece_idx * 64
        while diff:
            lsb = diff & (~diff + np.uint64(1))
            # Integer trailing-zero count (SF18-style)
            sq = numba.int32(0)
            tmp = lsb >> np.uint64(1)
            while tmp:
                sq += numba.int32(1)
                tmp >>= np.uint64(1)
            
            if old_piece_bbs[piece_idx] & lsb:
                removed[rem_idx] = offset + sq
                rem_idx += 1
            else:
                added[add_idx] = offset + sq
                add_idx += 1
                
            diff &= diff - np.uint64(1)
            
    return added, removed

@numba.njit(numba.int32(numba.types.Array(numba.uint64, 1, 'C')), fastmath=True, cache=True)
def evaluate_position_nn(piece_bbs):
    """
    Evaluates a chess position using the neural network directly from bitboards.
    This is mainly used in speed testing.
    """
    accumulator_stack = np.zeros((1, 2, 256), dtype=np.float32)
    init_accumulator(piece_bbs, accumulator_stack)
    logit = nnue_forward_incremental(0, 0, accumulator_stack) # assume White to move
    K = 0.00368208
    cp_score = numba.int32(logit / K)
    return cp_score

if __name__ == '__main__':
    if not weights_loaded:
        print("Cannot test inference without training weights. Please run train.py first.")
    else:
        # Simple test to verify compilation and execution
        print("Testing Numba Inference Engine...")
        import time
        
        # Initial Position test
        test_bbs = np.zeros(12, dtype=np.uint64)
        # White
        test_bbs[0] = np.uint64(0x000000000000FF00) # Pawns
        test_bbs[1] = np.uint64(0x0000000000000042) # Knights
        test_bbs[2] = np.uint64(0x0000000000000024) # Bishops
        test_bbs[3] = np.uint64(0x0000000000000081) # Rooks
        test_bbs[4] = np.uint64(0x0000000000000008) # Queen
        test_bbs[5] = np.uint64(0x0000000000000010) # King
        # Black
        test_bbs[6] = np.uint64(0x00FF000000000000) # Pawns
        test_bbs[7] = np.uint64(0x4200000000000000) # Knights
        test_bbs[8] = np.uint64(0x2400000000000000) # Bishops
        test_bbs[9] = np.uint64(0x8100000000000000) # Rooks
        test_bbs[10] = np.uint64(0x0800000000000000) # Queen
        test_bbs[11] = np.uint64(0x1000000000000000) # King
        
        print("Running NN eval on starting position (first run will trigger JIT compilation)...")
        start = time.perf_counter()
        score = evaluate_position_nn(test_bbs)
        end = time.perf_counter()
        print(f"Initial Pos Raw Centipawn score: {score:.2f}")
        print(f"Compilation + Execution time: {(end-start)*1000:.2f} ms")
        
        # Speed test
        print("Running speed test (1000 runs)...")
        start = time.perf_counter()
        for _ in range(1000):
            _ = evaluate_position_nn(test_bbs)
        end = time.perf_counter()
        print(f"1000 evals time: {(end-start)*1000:.2f} ms")
        print(f"Avgerage eval time: {(end-start)*1000/1000:.3f} ms/eval")
        print(f"NPS upper bound equivalent: {int(1000/(end-start)):,} nodes/sec")
        
        print("Inference Engine is ready!")
